outputs = ['aavke', 'abyab', 'ybckadb', 'adbewhew', 'abh']

# Let's manually examine each transformation
print("Detailed analysis:")
for i in range(len(inputs)):
    inp = inputs[i]
    outp = outputs[i]
    print(f"\n{i}: '{inp}' -> '{outp}'")

    # Find differences character by character
    diff_positions = []
    for j in range(min(len(inp), len(outp))):
        if inp[j] != outp[j]:
            diff_positions.append((j, inp[j], outp[j]))

    if len(inp) != len(outp):
        if len(inp) > len(outp):
            for j in range(len(outp), len(inp)):
                diff_positions.append((j, inp[j], 'DEL'))
        else:
            for j in range(len(inp), len(outp)):
                diff_positions.append((j, 'INS', outp[j]))

    print(f"  Differences: {diff_positions}")

